#!/usr/bin/env node
// Build two sections of each per-repo README (repos/<name>/README.md). The rest of the README
// comes from the regeneration recipe. Each section sits between its own BEGIN and END markers.
// - The "Start here" section, from estate.json, the repo's graph, and shared-resources.json. Its
//   "Shared resources" bullet links the sections of the shared-resource page where the repo
//   appears, or the page by its title (docs/shared-resources.md). If the repo has a note in
//   estate.json, the note comes first, right under the description. A regeneration drops the
//   markers, so the script inserts the section again before the first "##" heading.
// - The "Regenerating" section, which links the recipe by its title. Without the markers, the
//   section takes the place of the README's own "## Regenerating" section, or it goes at the end.
// It also checks what a regeneration tends to get wrong in the rest of the README: an em dash
// (this repo's text uses none), text that tells how to view the graphs (the Start here section
// does that, and recipe step 3 says not to), and a Regenerating heading that the script does
// not write.
// Usage: node build-repo-readmes.mjs           rewrite the sections
//        node build-repo-readmes.mjs --check   exit 1 if a section is stale or a check fails (CI)
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { EM_DASH, SHARED_RESOURCES_PAGE, fencedLines, isObject, loadEstate, markedBlock, readDocsFile, readGraph, readSharedResources, replaceMarked, root } from "./estate.mjs";

const SCRIPT = ".github/scripts/build-repo-readmes.mjs";
const START_HERE = {
  begin: `<!-- BEGIN start here: generated by ${SCRIPT} from estate.json, the graph, and shared-resources.json. Do not edit by hand. -->`,
  end: "<!-- END start here -->",
  what: "Start here section",
  optional: true,
};
const REGENERATING = {
  begin: `<!-- BEGIN regenerating: generated by ${SCRIPT}. Do not edit by hand. -->`,
  end: "<!-- END regenerating -->",
  what: "Regenerating section",
  optional: true,
};
const RECIPE = "docs/regenerating.md";
// A Regenerating heading: any level, any case, "#" or underline form ("Regenerating" + "---").
const REGENERATING_HEADING = /^ {0,3}(#{1,6}[ \t]+)?regenerating\b/i;
const SETEXT_UNDERLINE = /^ {0,3}(=+|-+)[ \t]*$/;
// The form that an older recipe asked for. Without the markers, the script replaces its section.
const OWN_HEADING = /^ {0,3}##[ \t]+regenerating[ \t]*#*[ \t]*$/i;
const VOLUNTEER_GUIDE = "../../docs/contribute-to-greenstand.md";
const ALL_FIRST_ISSUES =
  "https://github.com/search?q=org%3AGreenstand+label%3A%22good+first+issue%22+is%3Aissue+is%3Aopen+archived%3Afalse&type=issues&s=updated&o=desc";
const CODE_OF_CONDUCT =
  "https://github.com/Greenstand/Greenstand-Overview/blob/master/License%2C%20Code%20of%20Conduct%20etc/CODE_OF_CONDUCT.md";

const check = process.argv.includes("--check");
const { estate, repos, count, errors } = loadEstate();

// The title of a page of the docs repo: the first line of its file, "# <title>".
const titleOf = (at) =>
  readDocsFile(at, errors, (text) => {
    const title = text.match(/^# (.+)\n/)?.[1].trim();
    if (!title) throw new Error('the first line must be the title ("# <title>")');
    return title;
  });
const recipeTitle = titleOf(RECIPE);
const sharedResourcesTitle = titleOf(SHARED_RESOURCES_PAGE);
// A title or a name as Markdown link text: a "[" or "*" in it stays text.
const linkText = (title) => title.replace(/[\\`*_[\]<>]/g, "\\$&");

// The resources of shared-resources.json. The bullet reads only the id, the name, and the repo of
// each evidence entry; build-shared-resources.mjs checks the rest of the file.
const resources = readSharedResources(
  errors,
  "an id, a name, and an evidence list of objects",
  (r) => typeof r.id === "string" && typeof r.name === "string" && Array.isArray(r.evidence) && r.evidence.every(isObject),
);

// The path of the source repo's CONTRIBUTING.md, if it is a described file (a node in the
// graph), in the order of places that GitHub uses. The link points to the default branch
// (HEAD), which a new volunteer needs. If the file moves later, the drift report counts a
// removed described file.
const PLACES = [".github/contributing.md", "contributing.md", "docs/contributing.md"];
function contributingPath(name) {
  const graph = readGraph(name, errors);
  if (graph === null) return null;
  const paths = graph.nodes.map((n) => n.filePath).filter(Boolean);
  for (const place of PLACES) {
    const path = paths.find((p) => p.toLowerCase() === place);
    if (path) return path;
  }
  return null;
}

// The Shared resources bullet, as a list of lines. It links each section of the shared-resource
// page where the code repo appears in the evidence. The links follow the order of the data file,
// which is the order of the page. The link text is the ## heading of the section (the name of the
// resource), and the anchor is the id. A code repo in no section gets one link to the page. A docs
// repo gets no bullet.
function sharedResourcesBullet({ name, docs }) {
  if (docs || resources === null || sharedResourcesTitle === null) return [];
  const page = `../../${SHARED_RESOURCES_PAGE}`;
  const used = resources.filter((r) => r.evidence.some((e) => e.repo === name));
  if (!used.length) {
    return [`- **Shared resources:** see [${linkText(sharedResourcesTitle)}](${page}). The page says what the code repos share and who looks after each resource.`];
  }
  const links = used.map((r) => `[${linkText(r.name)}](${page}#${r.id})`).join(", ");
  const lead = used.length === 1 ? "The section tells" : "Each section tells";
  return [`- **Shared resources:** ${links}. ${lead} how this repo uses the resource and who looks after it.`];
}

// The text between the Start here markers. A repo with a note in estate.json gets the note first,
// so that it comes right after the description at the top of the README.
function startHereSection(repo) {
  const { name, source, note } = repo;
  const issues = `${source}/issues?q=is%3Aissue+is%3Aopen+label%3A%22good+first+issue%22`;
  const path = contributingPath(name);
  const readme = `[README](${source}#readme)`;
  const sourceDocs = path ? `the ${readme} and the [${path}](${source}/blob/HEAD/${path})` : `the ${readme}`;
  return [
    ...(note ? [note, ""] : []),
    "## Start here",
    "",
    `- **Explore:** open the [interactive viewer](${estate.siteUrl}${name}/). It has a guided tour of the repo. Then read the [onboarding guide](./ONBOARDING.md) and the [glossary](./GLOSSARY.md).`,
    `- **Source repo:** [Greenstand/${name}](${source}). Read ${sourceDocs} of the source repo before you make a change.`,
    ...sharedResourcesBullet(repo),
    `- **First tasks:** pick one from the [open good first issues](${issues}) of ${name}, or from the [good first issues of all Greenstand repos](${ALL_FIRST_ISSUES}).`,
    `- **New to Greenstand?** Read [How to contribute to Greenstand](${VOLUNTEER_GUIDE}). It tells you how to join the community and where to get help. Everyone follows Greenstand's [Code of Conduct](${CODE_OF_CONDUCT}).`,
  ].join("\n");
}

// The text between the Regenerating markers. It is the same in each README.
function regeneratingSection() {
  return ["## Regenerating", "", `To regenerate this documentation, follow [${linkText(recipeTitle)}](../../${RECIPE}).`].join("\n");
}

// The first "##" heading outside a code fence, from line from on, or null.
function firstHeading(lines, from = 0) {
  const fenced = fencedLines(lines);
  const i = lines.findIndex((line, k) => k >= from && !fenced[k] && line.startsWith("## "));
  return i === -1 ? null : i;
}

// Replace the marked Start here section, or insert it before the first "##" heading outside a
// code fence.
function spliceStartHere(readme, inner, at) {
  const replaced = replaceMarked(at, readme, START_HERE, inner, errors);
  if (replaced !== null) return replaced;
  const lines = readme.split("\n");
  const i = firstHeading(lines);
  if (i === null) return errors.push(`${at}: no "## " heading to put the Start here section before`), readme;
  return [...lines.slice(0, i), markedBlock(START_HERE, inner), "", ...lines.slice(i)].join("\n");
}

// The Regenerating headings outside a code fence and outside the Regenerating markers.
function regeneratingHeadings(lines) {
  const fenced = fencedLines(lines);
  let inSection = false;
  const found = [];
  lines.forEach((line, i) => {
    if (line === REGENERATING.begin) inSection = true;
    const underlined = i + 1 < lines.length && !fenced[i + 1] && SETEXT_UNDERLINE.test(lines[i + 1]);
    const match = line.match(REGENERATING_HEADING);
    if (!inSection && !fenced[i] && match && (match[1] || underlined)) found.push(i);
    if (line === REGENERATING.end) inSection = false;
  });
  return found;
}

const atEnd = (text, block) => `${text.replace(/\n*$/, "")}\n\n${block}\n`;

// The Regenerating headings that the script does not write: each one outside the markers. When
// the markers are missing, the README's own "## Regenerating" heading is not one of them.
function otherRegeneratingHeadings(lines) {
  const headings = regeneratingHeadings(lines);
  const hasMarkers = lines.includes(REGENERATING.begin) || lines.includes(REGENERATING.end);
  return !hasMarkers && OWN_HEADING.test(lines[headings[0]] ?? "") ? headings.slice(1) : headings;
}

// Replace the marked Regenerating section. Without the markers, replace the README's own
// "## Regenerating" section (up to the next "##" heading outside a code fence), or add the
// section at the end. Call it only when otherRegeneratingHeadings finds none.
function spliceRegenerating(readme, inner, at) {
  const replaced = replaceMarked(at, readme, REGENERATING, inner, errors);
  if (replaced !== null) return replaced;
  const block = markedBlock(REGENERATING, inner);
  const lines = readme.split("\n");
  const [own] = regeneratingHeadings(lines);
  if (own === undefined) return atEnd(readme, block);
  const end = firstHeading(lines, own + 1);
  if (end === null) return atEnd(lines.slice(0, own).join("\n"), block);
  return [...lines.slice(0, own), block, "", ...lines.slice(end)].join("\n");
}

// Check the README lines outside the Start here section.
function checkText(readme, at) {
  let inSection = false;
  readme.split("\n").forEach((line, i) => {
    if (line === START_HERE.begin) inSection = true;
    if (!inSection) {
      if (line.includes(EM_DASH)) errors.push(`${at}:${i + 1}: an em dash; use a colon, a comma, or two sentences`);
      if (line.includes(estate.siteUrl) || line.includes("understand-dashboard")) {
        errors.push(`${at}:${i + 1}: tells how to view the graphs; the Start here section does that`);
      }
    }
    if (line === START_HERE.end) inSection = false;
  });
}

const updates = [];
for (const repo of repos) {
  const at = `repos/${repo.name}/README.md`;
  const readme = readDocsFile(at, errors);
  if (readme === null) continue;
  checkText(readme, at);
  const before = errors.length;
  const withStartHere = spliceStartHere(readme, startHereSection(repo), at);
  const lines = withStartHere.split("\n");
  if (errors.length === before && lines[firstHeading(lines)] !== "## Start here") {
    errors.push(`${at}: the Start here section must come before the other "## " headings`);
  }
  // The line numbers of these errors are the lines of the README as it is on disk.
  const others = otherRegeneratingHeadings(readme.split("\n"));
  for (const i of others) {
    errors.push(`${at}:${i + 1}: a Regenerating heading that the script does not write. The script writes the Regenerating section. Delete this heading and its text.`);
  }
  const next = recipeTitle === null || others.length ? withStartHere : spliceRegenerating(withStartHere, regeneratingSection(), at);
  const staleSections = [withStartHere !== readme && "Start here", next !== withStartHere && "Regenerating"].filter(Boolean);
  updates.push({ at, next, staleSections });
}

if (errors.length) {
  for (const e of errors) console.error(`error: ${e}`);
  process.exit(1);
}

const stale = updates.filter((u) => u.staleSections.length);
if (check) {
  if (stale.length) {
    for (const u of stale) for (const what of u.staleSections) console.error(`error: the ${what} section of ${u.at} is stale`);
    console.error(`Run: node ${SCRIPT}`);
    process.exit(1);
  }
  console.log(`Start here and Regenerating sections are current (${count} repos)`);
} else {
  for (const { at, next } of stale) writeFileSync(join(root, at), next);
  console.log(`wrote the Start here and Regenerating sections (${count} repos, ${stale.length} changed)`);
}
